<template>
  <TooltipProvider :delay-duration="200">
    <div class="flex flex-col gap-4" data-testid="project-kickoff-view">
      <!-- Toolbar: last updated + edit -->
      <div class="flex flex-row flex-wrap items-center gap-x-4 gap-y-2">
        <EntityAuditInfo :audit="audit" class="!mt-0" data-testid="project-kickoff-updated" />
        <Button
          variant="outline"
          :prepend-icon="Pencil"
          class="ml-auto"
          data-testid="project-kickoff-edit-btn"
          @click="$emit('edit')"
        >
          Edit
        </Button>
      </div>

      <div class="grid grid-cols-1 gap-4 xl:grid-cols-3 items-start">
        <!-- WHO / WHAT: client identity, project type, description, contacts -->
        <Card class="xl:col-span-2" data-testid="project-kickoff-section-summary">
          <CardContent class="grid grid-cols-1 gap-6 pt-6 lg:grid-cols-[1fr_17rem]">
            <div class="flex min-w-0 flex-col gap-5">
              <div class="flex items-start gap-4">
                <div class="flex min-w-0 flex-col gap-1">
                  <h2
                    class="text-2xl font-semibold tracking-tight break-words"
