                  >
                    <MapPin class="mt-0.5 size-4 shrink-0" />
                    <span v-if="summary?.locations" class="whitespace-pre-line break-words">
                      Project locations: {{ text(summary?.locations) }}
                    </span>
                    <span v-else class="whitespace-pre-line break-words">No locations specified</span>
                  </div>
                </div>
              </div>

              <div class="flex flex-col gap-1.5" data-testid="project-kickoff-section-project-type">
                <span :class="LABEL_CLASS">Project Type</span>
                <div class="flex flex-wrap items-center gap-2" data-testid="project-kickoff-field-project-type">
                  <Badge v-if="typeBadge?.asBadge" :variant="typeBadge.variant" size="sm">{{ typeBadge.label }}</Badge>
                  <span v-else-if="typeBadge" class="text-sm font-medium">{{ typeBadge.label }}</span>
                  <span v-else class="text-sm text-muted-foreground">—</span>
                </div>
                <p
                  class="max-w-prose text-sm leading-6 whitespace-pre-line break-words"
                  :class="!projectTypeInfo?.description && 'text-muted-foreground'"
                  data-testid="project-kickoff-field-project-type-description"
                >
                  {{ text(projectTypeInfo?.description) }}
                </p>
              </div>

              <LabeledValue
                label="Candidate/Initiative Description"
                :label-class="LABEL_CLASS"
                value-class="line-clamp-none"
              >
                <span
                  class="block max-w-prose text-sm leading-6 whitespace-pre-line break-words"
                  :class="!summary?.project_description && 'text-muted-foreground'"
                  data-testid="project-kickoff-field-project-description"
                >
                  {{ text(summary?.project_description) }}
                </span>
              </LabeledValue>

              <div class="flex flex-col gap-1.5 border-t pt-4">
                <span class="flex items-center gap-1.5" :class="LABEL_CLASS">
                  <StickyNote class="size-3.5" /> Additional Notes
                </span>
                <p
                  class="max-w-prose text-sm leading-6 whitespace-pre-line break-words"
                  :class="!isNotesFilled(summary?.additional_notes) && 'text-muted-foreground'"
                  data-testid="project-kickoff-field-summary-additional-notes"
                >
                  {{ notesContent(summary?.additional_notes) }}
                </p>
              </div>
            </div>

            <div class="flex h-fit flex-col gap-3 rounded-lg bg-muted/50 p-4">
              <span :class="LABEL_CLASS">Contacts</span>
              <div
                class="flex flex-col gap-2 rounded-lg border bg-background p-3 shadow-sm"
                data-testid="project-kickoff-field-primary-contact"
              >
                <div class="flex items-center gap-1.5">
                  <span :class="CONTACT_BADGE_CLASS"><Phone class="size-4" /></span>
                  <span class="text-xs font-medium uppercase tracking-wide text-muted-foreground">Primary</span>
                </div>
                <KickoffContactDisplay :contact="summary?.primary_contact" empty-text="No primary contact" />
              </div>
              <div class="flex flex-col gap-2.5" data-testid="project-kickoff-field-supplemental-contacts">
                <template v-if="supplementalContacts.length > 0">
                  <div
                    v-for="(contact, index) in supplementalContacts"
                    :key="index"
                    class="flex flex-col gap-2 rounded-lg border bg-background p-3 shadow-sm"
                  >
                    <div class="flex items-center gap-1.5">
                      <span :class="CONTACT_BADGE_CLASS"><Users class="size-4" /></span>
                      <span class="text-xs font-medium uppercase tracking-wide text-muted-foreground"
                        >Contact {{ index + 1 }}</span
                      >
                    </div>
                    <KickoffContactDisplay :contact="contact" />
                  </div>
                </template>
                <span v-else class="text-xs text-muted-foreground">No supplemental contacts</span>
              </div>
            </div>
          </CardContent>
        </Card>

        <!-- HOW MUCH: universe stat tiles -->
        <div
          class="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4 xl:col-span-2"
          data-testid="project-kickoff-section-universe"
        >
          <Card
            v-for="tile in statTiles"
            :key="tile.id"
            class="flex flex-col gap-2 p-4"
            :class="tile.value === null && 'border-dashed bg-muted/20 shadow-none'"
            :data-testid="`project-kickoff-field-${tile.id}`"
          >
            <span class="w-fit rounded-md bg-primary/10 p-2">
              <component :is="tile.icon" class="size-4 text-primary" />
            </span>
            <Tooltip v-if="tile.hint">
              <TooltipTrigger as-child>
                <span class="w-fit text-3xl font-bold tabular-nums tracking-tight">{{ tile.value }}</span>
              </TooltipTrigger>
              <TooltipContent>{{ tile.hint }}</TooltipContent>
            </Tooltip>
            <span
              v-else
              class="text-3xl font-bold tabular-nums tracking-tight"
              :class="tile.value === null && 'text-muted-foreground/60'"
            >
              {{ tile.value ?? '—' }}
            </span>
            <span class="text-xs uppercase tracking-wide text-muted-foreground">{{ tile.label }}</span>
          </Card>
        </div>

        <!-- WHEN: timeline rail -->
        <!-- Content is absolutely positioned on lg+ so the rail's height follows the left column; the timeline scrolls inside. -->
        <Card
          class="relative col-span-full xl:col-start-3 xl:row-start-1 xl:row-span-2 xl:self-stretch"
          data-testid="project-kickoff-section-dates"
        >
          <div class="flex h-full flex-col xl:absolute xl:inset-0">
            <CardHeader class="shrink-0 pb-4">
              <div class="flex items-center justify-between gap-2">
                <CardTitle class="flex items-center gap-2 text-base">
                  <CalendarDays class="size-4 text-muted-foreground" /> Relevant Dates
                </CardTitle>
              </div>
              <div v-if="campaignProgress" class="flex items-center gap-2 pt-1">
                <Progress :model-value="campaignProgress.percent" class="h-1.5 flex-1 border-0" />
                <span class="whitespace-nowrap text-xs text-muted-foreground">
                  {{ campaignProgress.daysLeft }} day{{ campaignProgress.daysLeft === 1 ? '' : 's' }} left
                </span>
              </div>
            </CardHeader>
            <CardContent class="flex min-h-0 flex-1 flex-col gap-5">
              <div class="relative min-h-0 flex-1">
                <div
                  ref="timelineScroll"
                  class="h-full overflow-y-auto rounded-lg border bg-muted/20 p-3 [scrollbar-gutter:stable] [scrollbar-width:thin] [&::-webkit-scrollbar]:w-1.5 [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-border"
                >
                  <ol class="relative ml-2 flex min-h-full flex-col justify-between gap-5 border-l border-border pl-5">
                    <li
                      v-for="entry in timelineView.scheduled"
                      :key="entry.id"
                      class="relative"
                      :data-testid="`project-kickoff-field-${entry.id}`"
                    >
                      <span
                        class="absolute -left-[25px] top-0.5 size-2.5 rounded-full ring-4 ring-card"
                        :class="entry.dotClass"
                      />
                      <div class="flex flex-col gap-0.5">
                        <span :class="LABEL_CLASS">{{ entry.label }}</span>
                        <div class="flex flex-wrap items-center gap-2">
                          <span class="text-sm font-semibold tabular-nums">{{ entry.dateText }}</span>
                          <Badge :variant="entry.chip.variant" size="sm" class="normal-case">{{
                            entry.chip.label
                          }}</Badge>
                        </div>
                      </div>
                    </li>
                    <template v-if="timelineView.unscheduled.length > 0">
                      <li class="text-xs uppercase tracking-wide text-muted-foreground/70">Not scheduled</li>
                      <li
                        v-for="entry in timelineView.unscheduled"
                        :key="entry.id"
                        class="relative"
                        :data-testid="`project-kickoff-field-${entry.id}`"
                      >
                        <span
                          class="absolute -left-[25px] top-0.5 size-2.5 rounded-full border border-muted-foreground/40 bg-card ring-4 ring-card"
                        />
                        <div class="flex flex-col gap-0.5">
                          <span :class="LABEL_CLASS">{{ entry.label }}</span>
                          <span class="text-sm text-muted-foreground">—</span>
                        </div>
                      </li>
                    </template>
                  </ol>
                </div>

                <!-- Top fade: more dates above -->
                <div
                  aria-hidden="true"
                  class="pointer-events-none absolute inset-x-px top-px h-6 rounded-t-lg bg-gradient-to-b from-card to-transparent transition-opacity duration-200"
                  :class="canScrollUp ? 'opacity-100' : 'opacity-0'"
                />
                <!-- Bottom fade + nudge chevron: more dates below -->
                <div
                  aria-hidden="true"
                  class="pointer-events-none absolute inset-x-px bottom-px flex h-9 items-end justify-center rounded-b-lg bg-gradient-to-t from-card to-transparent pb-1 transition-opacity duration-200"
                  :class="canScrollDown ? 'opacity-100' : 'opacity-0'"
                >
                  <ChevronDown class="size-4 animate-bounce text-muted-foreground" />
                </div>
              </div>

              <Alert
                v-if="disruptions"
                variant="warning"
                class="shrink-0"
                data-testid="project-kickoff-field-possible-disruptions"
              >
                <TriangleAlert />
                <AlertTitle class="text-sm">Possible Disruptions</AlertTitle>
                <AlertDescription class="text-sm">
                  <div class="relative">
                    <div
                      ref="disruptionsScroll"
                      class="max-h-32 overflow-y-auto whitespace-pre-line break-words [scrollbar-gutter:stable] [scrollbar-width:thin] [&::-webkit-scrollbar]:w-1.5 [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-warning-foreground/30"
                    >
                      {{ disruptions }}
                    </div>
                    <!-- Top fade: more text above -->
                    <div
                      aria-hidden="true"
                      class="pointer-events-none absolute inset-x-0 top-0 h-5 bg-gradient-to-b from-card to-transparent transition-opacity duration-200"
                      :class="disruptionsCanScrollUp ? 'opacity-100' : 'opacity-0'"
                    />
                    <!-- Bottom fade + nudge chevron: more text below -->
                    <div
                      aria-hidden="true"
                      class="pointer-events-none absolute inset-x-0 bottom-0 flex h-6 items-end justify-center bg-gradient-to-t from-card to-transparent transition-opacity duration-200"
                      :class="disruptionsCanScrollDown ? 'opacity-100' : 'opacity-0'"
                    >
                      <ChevronDown class="size-3.5 animate-bounce text-warning-foreground" />
                    </div>
                  </div>
                </AlertDescription>
              </Alert>
              <p
                v-else
                class="flex shrink-0 items-center gap-2 rounded-lg border border-dashed p-3 text-xs text-muted-foreground"
                data-testid="project-kickoff-field-possible-disruptions"
              >
                <TriangleAlert class="size-3.5 shrink-0 opacity-50" /> No known disruptions
              </p>
            </CardContent>
          </div>
        </Card>

        <!-- LOGISTICS: reporting, app/data/literature, misc -->
        <Card class="xl:col-span-3">
          <CardContent class="grid grid-cols-1 gap-8 pt-6 md:grid-cols-3 md:gap-6">
            <section
              v-for="column in logisticsColumns"
              :key="column.id"
              class="flex min-w-0 flex-col gap-4"
              :data-testid="`project-kickoff-section-${column.id}`"
            >
              <div class="flex items-center gap-2">
                <component :is="column.icon" class="size-4 shrink-0 text-muted-foreground" />
                <h3 class="text-xs font-semibold uppercase tracking-wide text-muted-foreground">{{ column.title }}</h3>
                <span class="h-px flex-1 bg-border" />
                <SectionCounterTooltip :stats="sectionStats[column.id]" />
              </div>
              <div class="flex flex-col gap-3">
                <template v-for="field in column.fields" :key="field.id">
                  <div
                    v-if="field.kind === 'bool'"
                    class="flex items-center gap-2"
                    :data-testid="`project-kickoff-field-${field.id}`"
                  >
                    <CircleCheck v-if="field.bool === true" class="size-4 shrink-0 text-success-foreground" />
                    <CircleX v-else-if="field.bool === false" class="size-4 shrink-0 text-destructive" />
                    <CircleDashed v-else class="size-4 shrink-0 text-muted-foreground/50" />
                    <span class="text-sm">{{ field.label }}</span>
                    <span class="ml-auto text-xs text-muted-foreground">{{ yesNo(field.bool) }}</span>
                  </div>
                  <LabeledValue
                    v-else-if="field.kind === 'contact'"
                    :label="field.label"
                    :label-class="LABEL_CLASS"
                    value-class="line-clamp-none"
                    :data-testid="`project-kickoff-field-${field.id}`"
                  >
                    <KickoffContactDisplay :contact="field.contact" />
                  </LabeledValue>
                  <LabeledValue
                    v-else
                    :label="field.label"
                    :label-class="LABEL_CLASS"
                    value-class="line-clamp-none"
                    :data-testid="`project-kickoff-field-${field.id}`"
                  >
                    <span
                      class="block whitespace-pre-line break-words text-sm font-medium"
                      :class="field.value === EMPTY && 'font-normal text-muted-foreground'"
                    >
                      {{ field.value }}
                    </span>
                  </LabeledValue>
                </template>
              </div>
            </section>
          </CardContent>
        </Card>
      </div>
    </div>
  </TooltipProvider>
</template>

<script setup lang="ts">
import type { Component } from 'vue';
import {
  CalendarDays,
  ChevronDown,
  CircleCheck,
  CircleDashed,
  CircleX,
  ClipboardList,
  DoorOpen,
  Gauge,
  Home,
  MapPin,
  MessagesSquare,
  AppWindow,
  Pencil,
  Phone,
  Repeat2,
  StickyNote,
  TriangleAlert,
  Users,
} from 'lucide-vue-next';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Progress } from '@/components/ui/progress';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import type { AuditInfo, KickoffContact, ProjectKickoffNotes } from '~/client';
import { getKickoffProjectTypeVariant } from '~/constants/projects/kickoffProjectTypeBadgeConfig';

const props = defineProps<{
  kickoffNotes: ProjectKickoffNotes;
}>();

defineEmits<{
  edit: [];
}>();

const EMPTY = '—';

// Shared style for the uppercase micro-labels used across the tab (plain spans and LabeledValue's label-class).
const LABEL_CLASS = 'text-xs font-medium uppercase tracking-wide text-muted-foreground';

// Star / numbered chip that identifies each contact card in the Contacts panel.
const CONTACT_BADGE_CLASS =
  'inline-flex size-6 shrink-0 items-center justify-center rounded-full bg-primary/10 text-[0.7rem] font-semibold text-primary tabular-nums';

const summary = computed(() => props.kickoffNotes.summary);
const projectTypeInfo = computed(() => props.kickoffNotes.project_type);
const datesInfo = computed(() => props.kickoffNotes.dates);
const universeInfo = computed(() => props.kickoffNotes.universe);
const reportingInfo = computed(() => props.kickoffNotes.reporting);
const appDataInfo = computed(() => props.kickoffNotes.app_data_literature);
const additionalInfo = computed(() => props.kickoffNotes.additional_notes);

function text(value: string | null | undefined): string {
  return value && value.length > 0 ? value : EMPTY;
}

function date(value: string | null | undefined): string {
  return value ? formatUTCDateString(value, 'MM/dd/yyyy') : EMPTY;
}

function yesNo(value: boolean | null | undefined): string {
  if (value === true) return 'Yes';
  if (value === false) return 'No';
  return 'Not set';
}

function notesContent(value: { [key: string]: string } | string | null | undefined): string {
  if (!value) return EMPTY;
  if (typeof value === 'string') return text(value);
  const entries = Object.entries(value);
  return entries.length > 0 ? entries.map(([key, val]) => `${key}: ${val}`).join('\n') : EMPTY;
}

function isNotesFilled(value: { [key: string]: string } | string | null | undefined): boolean {
  if (!value) return false;
  return typeof value === 'string' ? value.trim().length > 0 : Object.keys(value).length > 0;
}

// --- Identity -------------------------------------------------------------

const audit = computed<AuditInfo>(() => ({
  updated_at: props.kickoffNotes.updated_at,
  updated_by: props.kickoffNotes.updated_by ?? null,
}));

const typeBadge = computed(() => {
  const raw = projectTypeInfo.value?.project_type?.trim();
  if (!raw) return null;
  // Badge applies `capitalize` + rounded-full; long free-text types read better as plain text.
  return { label: raw, variant: getKickoffProjectTypeVariant(raw), asBadge: raw.length <= 24 };
});

const supplementalContacts = computed(() => summary.value?.supplemental_contacts ?? []);

// --- Timeline ---------------------------------------------------------------

const today = new Date();

const campaignProgress = computed(() =>
  getKickoffCampaignProgress(datesInfo.value?.start_date, datesInfo.value?.end_date, today)
);

const disruptions = computed(() => {
  const value = datesInfo.value?.possible_disruptions;
  return value && value.trim().length > 0 ? value : null;
});

const timelineView = computed(() => {
  const timeline = buildKickoffTimeline(datesInfo.value);
  const scheduled = timeline.scheduled.map((entry) => ({
    ...entry,
    dateText: date(entry.date),
    chip: getKickoffDateChip(entry.date as string, today, entry.isDropDead),
  }));
  const nextIndex = scheduled.findIndex((entry) => entry.chip.days >= 0);
  return {
    scheduled: scheduled.map((entry, index) => ({
      ...entry,
      dotClass:
        entry.isDropDead && entry.chip.days >= 0
          ? 'bg-destructive'
          : entry.chip.days === 0
            ? 'bg-primary animate-pulse'
            : index === nextIndex
              ? 'bg-primary'
              : entry.chip.days < 0
                ? 'bg-muted-foreground/30'
                : 'border border-muted-foreground/40 bg-card',
    })),
    unscheduled: timeline.unscheduled,
  };
});

const timelineScroll = ref<HTMLElement | null>(null);
const { canScrollUp, canScrollDown } = useScrollAffordance(timelineScroll, timelineView);

const disruptionsScroll = ref<HTMLElement | null>(null);
const { canScrollUp: disruptionsCanScrollUp, canScrollDown: disruptionsCanScrollDown } = useScrollAffordance(
  disruptionsScroll,
  disruptions
);

// --- Universe stat tiles ----------------------------------------------------

function formatStat(value: number | null | undefined): string | null {
  return value === null || value === undefined ? null : value.toLocaleString('en-US', { maximumFractionDigits: 2 });
}

interface StatTile {
  id: string;
  label: string;
  icon: Component;
  value: string | null;
  hint?: string;
}

const statTiles = computed<StatTile[]>(() => {
  const universe = universeInfo.value;
  const doors = universe?.doors_in_universe;
  const passes = universe?.passes_on_universe;
  const crossCheck =
    doors && passes
      ? `${doors.toLocaleString('en-US')} doors × ${passes.toLocaleString('en-US')} passes = ${(doors * passes).toLocaleString('en-US')}`
      : undefined;
  return [
    {
      id: 'total-door-knocks',
      label: 'Total Door Knocks',
      icon: DoorOpen,
      value: formatStat(universe?.total_door_knocks),
      hint: universe?.total_door_knocks ? crossCheck : undefined,
    },
    { id: 'doors-in-universe', label: 'Doors in Universe', icon: Home, value: formatStat(doors) },
    { id: 'passes-on-universe', label: 'Passes on Universe', icon: Repeat2, value: formatStat(passes) },
    {
      id: 'door-per-hour-goal',
      label: 'Door Per Hour Goal',
      icon: Gauge,
      value: formatStat(universe?.door_per_hour_goal),
    },
  ];
});

// --- Logistics columns --------------------------------------------------------

interface LogisticsField {
  id: string;
  label: string;
  kind: 'text' | 'bool' | 'contact';
  value?: string;
  bool?: boolean | null;
  contact?: KickoffContact | null;
}

interface LogisticsColumn {
  id: 'reporting' | 'app-data-literature' | 'additional-notes';
  title: string;
  icon: Component;
  fields: LogisticsField[];
}

const logisticsColumns = computed<LogisticsColumn[]>(() => [
  {
    id: 'reporting',
    title: 'Reporting & Interface',
    icon: MessagesSquare,
    fields: [
      {
        id: 'reporting-contact',
        label: 'Reporting Contact',
        kind: 'contact',
        contact: reportingInfo.value?.reporting_contact,
      },
      {
        id: 'meeting-cadence',
        label: 'Meeting Cadence',
        kind: 'text',
        value: text(reportingInfo.value?.meeting_cadence),
      },
      {
        id: 'report-frequency',
        label: 'Report Frequency',
        kind: 'text',
        value: text(reportingInfo.value?.report_frequency),
      },
    ],
  },
  {
    id: 'app-data-literature',
    title: 'App, Data & Literature',
    icon: AppWindow,
    fields: [
      { id: 'project-app', label: 'Project App', kind: 'text', value: text(appDataInfo.value?.project_app) },
      {
        id: 'app-provided-by',
        label: 'App Provided By',
        kind: 'text',
        value: text(appDataInfo.value?.app_provided_by),
      },
      {
        id: 'data-provided-by',
        label: 'Data Provided By',
        kind: 'text',
        value: text(appDataInfo.value?.data_provided_by),
      },
      {
        id: 'survey-provided-by',
        label: 'Survey Provided By',
        kind: 'text',
        value: text(appDataInfo.value?.survey_provided_by),
      },
      {
        id: 'literature-date',
        label: 'Literature Date',
        kind: 'text',
        value: date(appDataInfo.value?.literature_date),
      },
      {
        id: 'app-data-additional-notes',
        label: 'Notes',
        kind: 'text',
        value: notesContent(appDataInfo.value?.additional_notes),
      },
    ],
  },
  {
    id: 'additional-notes',
    title: 'Additional',
    icon: ClipboardList,
    fields: [
      { id: 'note-taking', label: 'Note Taking', kind: 'bool', bool: additionalInfo.value?.note_taking },
      { id: 'qa-calls', label: 'QA Calls', kind: 'bool', bool: additionalInfo.value?.qa_calls },
      {
        id: 'campaign-apparel-provided',
        label: 'Campaign Apparel Provided',
        kind: 'bool',
        bool: additionalInfo.value?.campaign_apparel_provided,
      },
      { id: 'other-notes', label: 'Other', kind: 'text', value: notesContent(additionalInfo.value?.other) },
    ],
  },
]);

// --- Completeness -------------------------------------------------------------

function isStrFilled(value: string | null | undefined): boolean {
  return !!value && value.trim().length > 0;
}

function isBoolFilled(value: boolean | null | undefined): boolean {
  return value === true || value === false;
}

function isContactFilled(contact: KickoffContact | null | undefined): boolean {
  return !!contact && (isStrFilled(contact.name) || isStrFilled(contact.phone) || isStrFilled(contact.email));
}

interface SectionCompleteness {
  id: string;
  title: string;
  checks: [label: string, filled: boolean][];
}

const completenessSections = computed<SectionCompleteness[]>(() => {
  const notes = props.kickoffNotes;
  return [
    {
      id: 'reporting',
      title: 'Reporting & Interface',
      checks: [
        ['Reporting Contact', isContactFilled(notes.reporting?.reporting_contact)],
        ['Meeting Cadence', isStrFilled(notes.reporting?.meeting_cadence)],
        ['Report Frequency', isStrFilled(notes.reporting?.report_frequency)],
      ],
    },
    {
      id: 'app-data-literature',
      title: 'App, Data & Literature',
      checks: [
        ['Project App', isStrFilled(notes.app_data_literature?.project_app)],
        ['App Provided By', isStrFilled(notes.app_data_literature?.app_provided_by)],
        ['Data Provided By', isStrFilled(notes.app_data_literature?.data_provided_by)],
        ['Survey Provided By', isStrFilled(notes.app_data_literature?.survey_provided_by)],
        ['Literature Date', isStrFilled(notes.app_data_literature?.literature_date)],
        ['Additional Notes', isNotesFilled(notes.app_data_literature?.additional_notes)],
      ],
    },
    {
      id: 'additional-notes',
      title: 'Additional Notes',
      checks: [
        ['Note Taking', isBoolFilled(notes.additional_notes?.note_taking)],
        ['QA Calls', isBoolFilled(notes.additional_notes?.qa_calls)],
        ['Campaign Apparel Provided', isBoolFilled(notes.additional_notes?.campaign_apparel_provided)],
        ['Other', isNotesFilled(notes.additional_notes?.other)],
      ],
    },
  ];
});

interface SectionStats {
  filled: number;
  total: number;
  missing: string[];
}

const sectionStats = computed<Record<string, SectionStats>>(() =>
  Object.fromEntries(
    completenessSections.value.map((section) => [
      section.id,
      {
        filled: section.checks.filter(([, filled]) => filled).length,
        total: section.checks.length,
        missing: section.checks.filter(([, filled]) => !filled).map(([label]) => label),
      },
    ])
  )
);
</script>
