<script setup lang="ts">
import { useFieldArray, useForm } from 'vee-validate';
import {
  AppWindow,
  CalendarDays,
  ClipboardList,
  Gauge,
  MessagesSquare,
  Phone,
  Plus,
  Trash,
  Users,
} from 'lucide-vue-next';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import DatePicker from '@/components/ui/date-picker/DatePicker.vue';
import type { ProjectKickoffNotes, ProjectKickoffNotesPatchRequest } from '~/client';
import {
  buildKickoffPatch,
  kickoffFormValuesFromNotes,
  projectKickoffNotesFormSchema,
} from '~/constants/validationSchemas/projectKickoffNotes';
import type { SelectItem } from '~/types/selectItem';

const props = defineProps<{
  kickoffNotes: ProjectKickoffNotes | null;
  isSaving: boolean;
}>();

const emit = defineEmits<{
  save: [payload: ProjectKickoffNotesPatchRequest];
  cancel: [];
}>();

const yesNoItems: SelectItem[] = [
  { name: 'Not set', value: 'unset' },
  { name: 'Yes', value: 'yes' },
  { name: 'No', value: 'no' },
];

const initialValues = kickoffFormValuesFromNotes(props.kickoffNotes);
const initialSnapshot = structuredClone(initialValues);

const { handleSubmit } = useForm({
  validationSchema: projectKickoffNotesFormSchema,
  initialValues,
});

const {
  fields: contactFields,
  push: addContact,
  remove: removeContact,
} = useFieldArray<{ name?: string; phone?: string; email?: string }>('supplemental_contacts');
const {
  fields: importantDateFields,
  push: addImportantDate,
  remove: removeImportantDate,
} = useFieldArray<{ label: string; date: string | undefined }>('other_important_dates');

const onSubmit = handleSubmit((values) => {
  emit('save', buildKickoffPatch(values, initialSnapshot));
});
</script>
