import { getProjectKickoffNotes } from '~/client';

export const useProjectKickoffNotes = defineQuery(() => {
  const route = useRoute('projects-id-kickoff');
  const projectId = computed(() => route.params.id?.toString() || '');
  const queryCache = useQueryCache();

  const { data, error, isLoading, refetch } = useQuery({
    key: () => ['project.kickoff-notes', projectId.value],
    query: async () => {
      const response = await getProjectKickoffNotes({ composable: '$fetch', path: { project_id: projectId.value } });
      // Prime the short-info cache with the server-resolved editor so InlineEntityUser can render
      // the name even when the editor is outside the viewer's user visibility (a manager cannot
      // fetch admins via /user/{id}/short_info).
      if (response.updated_by_user) {
        queryCache.setQueryData(['user.short-info', response.updated_by_user.id], response.updated_by_user);
      }
      return response;
    },
    enabled: () => !!projectId.value && route.name === 'projects-id-kickoff',
  });

  const kickoffNotes = computed(() => data.value?.kickoff_notes ?? null);

  return {
    projectId,
    kickoffNotes,
    error,
    isLoading,
    refetch,
  };
});
