import type { Ref, WatchSource } from 'vue';
import { useResizeObserver, useScroll } from '@vueuse/core';

// Sub-pixel slack so the fades don't flicker on/off at the extremes.
const SCROLL_FADE_THRESHOLD = 4;

/**
 * Tracks whether a scroll container has content hidden above/below the viewport, so the UI can
 * hint at overflow (edge fades, a nudge chevron) instead of relying on a persistent scrollbar.
 *
 * @param el - template ref to the scrollable element (`overflow-y-auto`).
 * @param contentSource - optional watch source that changes when the content does; a resize
 *   observer only fires on box-size changes, so pass this to re-measure when the element keeps a
 *   fixed height but its content grows/shrinks (e.g. a reactive list).
 */
export function useScrollAffordance(el: Ref<HTMLElement | null>, contentSource?: WatchSource) {
  const { y } = useScroll(el);
  const scrollHeight = ref(0);
  const clientHeight = ref(0);

  function measure() {
    const node = el.value;
    if (!node) return;
    scrollHeight.value = node.scrollHeight;
    clientHeight.value = node.clientHeight;
  }

  useResizeObserver(el, measure);
  onMounted(measure);
  if (contentSource) watch(contentSource, () => nextTick(measure));

  const canScrollUp = computed(() => y.value > SCROLL_FADE_THRESHOLD);
  const canScrollDown = computed(() => scrollHeight.value - clientHeight.value - y.value > SCROLL_FADE_THRESHOLD);

  return { canScrollUp, canScrollDown, measure };
}
