import { differenceInCalendarDays } from 'date-fns';
import type { KickoffRelevantDates } from '~/client';
import type { BadgeVariants } from '@/components/ui/badge';

/** Parse a `yyyy-MM-dd` string to a Date at local midnight so calendar-day math has no timezone off-by-one. */
export function parseDateOnly(dateStr: string): Date {
  const [y, m, d] = dateStr.split('-').map(Number);
  return new Date(y, m - 1, d);
}

export interface KickoffDateChip {
  /** Calendar days from `today` to the date; negative for past dates. */
  days: number;
  label: string;
  variant: BadgeVariants;
}

/**
 * Relative-urgency chip for a kickoff milestone. Color encodes urgency, never celebration:
 * past → neutral, far future → success, ≤14 days → warning, today → warning (destructive for drop-dead).
 * Drop-dead dates escalate to destructive already at ≤7 days out.
 */
export function getKickoffDateChip(dateStr: string, today: Date, isDropDead: boolean = false): KickoffDateChip {
  const days = differenceInCalendarDays(parseDateOnly(dateStr), today);
  if (days < 0) {
    const ago = Math.abs(days);
    return { days, label: `${ago} day${ago === 1 ? '' : 's'} ago`, variant: 'default' };
  }
  if (days === 0) return { days, label: 'Today', variant: isDropDead ? 'destructive' : 'warning' };
  const label = `In ${days} day${days === 1 ? '' : 's'}`;
  if (isDropDead && days <= 7) return { days, label, variant: 'destructive' };
  if (days <= 14) return { days, label, variant: 'warning' };
  return { days, label, variant: 'success' };
}

export interface KickoffTimelineEntry {
  /** Field id used for `project-kickoff-field-<id>` test ids. */
  id: string;
  label: string;
  date: string | null;
  isDropDead: boolean;
}

export interface KickoffTimeline {
  /** Entries with a date, sorted chronologically (fixed milestones merged with other important dates). */
  scheduled: KickoffTimelineEntry[];
  /** Fixed milestones without a date, so gaps stay visible. */
  unscheduled: KickoffTimelineEntry[];
}

export function buildKickoffTimeline(dates: KickoffRelevantDates | null | undefined): KickoffTimeline {
  const milestones: KickoffTimelineEntry[] = [
    { id: 'start-date', label: 'Start', date: dates?.start_date ?? null, isDropDead: false },
    { id: 'end-date', label: 'End', date: dates?.end_date ?? null, isDropDead: false },
    {
      id: 'target-completion-date',
      label: 'Target Completion',
      date: dates?.target_completion_date ?? null,
      isDropDead: false,
    },
    { id: 'election-date', label: 'Election / Drop Dead', date: dates?.election_date ?? null, isDropDead: true },
  ];
  const others: KickoffTimelineEntry[] = Object.entries(dates?.other_important_dates ?? {})
    .filter(([, date]) => !!date)
    .map(([label, date], index) => ({ id: `other-important-dates-${index}`, label, date, isDropDead: false }));

  const scheduled = [...milestones.filter((m) => m.date), ...others].sort((a, b) =>
    (a.date as string).localeCompare(b.date as string)
  );
  return { scheduled, unscheduled: milestones.filter((m) => !m.date) };
}

export interface KickoffCampaignProgress {
  /** 0-100, share of the start→end range elapsed as of `today`. */
  percent: number;
  daysLeft: number;
}

export function getKickoffCampaignProgress(
  startStr: string | null | undefined,
  endStr: string | null | undefined,
  today: Date
): KickoffCampaignProgress | null {
  if (!startStr || !endStr) return null;
  const start = parseDateOnly(startStr);
  const end = parseDateOnly(endStr);
  const totalDays = differenceInCalendarDays(end, start);
  if (totalDays < 0) return null;
  const elapsed = differenceInCalendarDays(today, start);
  const percent =
    totalDays === 0 ? (elapsed >= 0 ? 100 : 0) : Math.round(Math.min(100, Math.max(0, (elapsed / totalDays) * 100)));
  return { percent, daysLeft: Math.max(0, differenceInCalendarDays(end, today)) };
}
