import type { BadgeVariants } from '~/components/ui/badge';

/**
 * Badge variants for known kickoff project types (free-text field, matched case-insensitively).
 * Unknown types fall back to the neutral badge.
 */
const kickoffProjectTypeVariants: Record<string, BadgeVariants> = {
  canvassing: 'teal',
  signature: 'violet',
};

export function getKickoffProjectTypeVariant(projectType: string): BadgeVariants {
  return kickoffProjectTypeVariants[projectType.trim().toLowerCase()] ?? 'default';
}
