<template>
  <div v-if="rows.length > 0" class="flex flex-col gap-1.5">
    <div v-for="row in rows" :key="row.key" class="flex items-start gap-2" :data-testid="`kickoff-contact-${row.key}`">
      <div class="flex min-w-0 flex-1 flex-col">
        <span class="text-xs text-muted-foreground">{{ row.label }}</span>
        <span class="break-words text-sm font-medium">{{ row.value }}</span>
      </div>
      <Tooltip>
        <TooltipTrigger as-child>
          <Button variant="ghost" size="icon" type="button" class="size-7 shrink-0" @click="onCopy(row)">
            <Check v-if="isCopied && copiedKey === row.key" class="size-3.5" />
            <Copy v-else class="size-3.5" />
          </Button>
        </TooltipTrigger>
        <TooltipContent>Copy {{ row.label.toLowerCase() }}</TooltipContent>
      </Tooltip>
    </div>
  </div>
  <span v-else class="text-sm text-muted-foreground">{{ emptyText }}</span>
</template>

<script setup lang="ts">
import { Check, Copy } from 'lucide-vue-next';
import { Button } from '@/components/ui/button';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import type { KickoffContact } from '~/client';

const props = withDefaults(defineProps<{ contact: KickoffContact | null | undefined; emptyText?: string }>(), {
  emptyText: '—',
});

interface ContactRow {
  key: string;
  label: string;
  value: string;
}

const { copy, isCopied } = useCopyToClipboard();
const copiedKey = ref<string | null>(null);

const rows = computed<ContactRow[]>(() =>
  (
    [
      { key: 'name', label: 'Name', value: props.contact?.name },
      { key: 'phone', label: 'Phone', value: props.contact?.phone },
      { key: 'email', label: 'Email', value: props.contact?.email },
    ] as { key: string; label: string; value: string | null | undefined }[]
  ).filter((row): row is ContactRow => !!row.value && row.value.trim().length > 0)
);

async function onCopy(row: ContactRow) {
  copiedKey.value = row.key;
  await copy(row.value);
}
</script>
