<template>
  <section class="flex flex-col gap-4">
    <template v-if="isLoading">
      <div class="flex flex-row items-center justify-between">
        <Skeleton class="h-5 w-64" />
        <Skeleton class="h-10 w-24" />
      </div>
      <div class="grid grid-cols-1 gap-4 xl:grid-cols-3">
        <Skeleton class="h-64 rounded-xl xl:col-span-2" />
        <Skeleton class="h-40 rounded-xl xl:col-span-2" />
        <Skeleton class="h-[26rem] rounded-xl xl:col-start-3 xl:row-start-1 xl:row-span-2" />
        <Skeleton class="h-48 rounded-xl xl:col-span-3" />
      </div>
    </template>
    <template v-else-if="isEditing">
      <ProjectKickoffForm
        :kickoff-notes="kickoffNotes"
        :is-saving="isProjectKickoffNotesPatchLoading"
        @save="onSave"
        @cancel="isEditing = false"
      />
    </template>
    <template v-else-if="kickoffNotes">
      <ProjectKickoffView :kickoff-notes="kickoffNotes" @edit="isEditing = true" />
    </template>
    <template v-else-if="error">
      <AppError
        title="Failed to load kickoff notes"
        :error="error"
        :action="refetch"
        action-text="Retry"
        data-testid="project-kickoff-error"
      />
    </template>
    <template v-else>
      <div
        class="flex flex-col items-center justify-center gap-4 py-16 border border-dashed rounded-xl"
        data-testid="project-kickoff-empty-state"
      >
        <p class="text-sm text-muted-foreground text-center px-4">
          No kickoff notes have been added yet. Capture the kickoff call details to share them with the team.
        </p>
        <Button
          :prepend-icon="NotebookPenIcon"
          :loading="isProjectKickoffNotesPatchLoading"
          data-testid="project-kickoff-add-btn"
          @click="onCreate"
        >
          Add Kickoff Notes
        </Button>
      </div>
    </template>
  </section>
</template>

<script setup lang="ts">
import { NotebookPenIcon } from 'lucide-vue-next';
import { Button } from '@/components/ui/button';
import { Skeleton } from '@/components/ui/skeleton';
import type { ProjectKickoffNotesPatchRequest } from '~/client';
import { useProjectKickoffNotesPatch } from '~/mutations/project/kickoff/patch';

definePageMeta({
  backGroup: 'project-details',
  roles: ['admin', 'manager'],
  backLabel: 'project',
});

const { projectId, kickoffNotes, isLoading, error, refetch } = useProjectKickoffNotes();
const { projectKickoffNotesPatch, isProjectKickoffNotesPatchLoading } = useProjectKickoffNotesPatch();

const isEditing = ref<boolean>(false);

async function onCreate() {
  try {
    await projectKickoffNotesPatch({ projectId: projectId.value, body: {} });
    isEditing.value = true;
  } catch {
    // Error toast is shown by the mutation; keep the empty state available for retry.
  }
}

async function onSave(payload: ProjectKickoffNotesPatchRequest) {
  if (Object.keys(payload).length === 0) {
    isEditing.value = false;
    return;
  }

  try {
    await projectKickoffNotesPatch({ projectId: projectId.value, body: payload });
    isEditing.value = false;
  } catch {
    // Error toast is shown by the mutation; stay in edit mode so input is not lost.
  }
}
</script>
