<template>
  <span v-if="stats && stats.missing.length === 0" class="cursor-default text-xs tabular-nums text-muted-foreground">
    {{ stats.filled }}/{{ stats.total }}
  </span>
  <Tooltip v-else-if="stats">
    <TooltipTrigger as-child>
      <span class="cursor-default text-xs tabular-nums text-muted-foreground"
        >{{ stats.filled }}/{{ stats.total }}</span
      >
    </TooltipTrigger>
    <TooltipContent side="left" class="max-w-xs">
      <p class="text-xs">Missing: {{ stats.missing.join(', ') }}</p>
    </TooltipContent>
  </Tooltip>
</template>

<script setup lang="ts">
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';

defineProps<{
  stats?: {
    filled: number;
    total: number;
    missing: string[];
  };
}>();
</script>
