import {
  patchProjectKickoffNotes,
  type PatchProjectKickoffNotesResponse,
  type ProjectKickoffNotesPatchRequest,
} from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useProjectKickoffNotesPatch = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (vars: {
      projectId: string;
      body: ProjectKickoffNotesPatchRequest;
    }): Promise<PatchProjectKickoffNotesResponse> =>
      patchProjectKickoffNotes({
        composable: '$fetch',
        path: { project_id: vars.projectId },
        body: ref(vars.body),
      }),
    onSuccess: async (response, { projectId, body }) => {
      queryCache.setQueryData(['project.kickoff-notes', projectId], response);
      if (response.updated_by_user) {
        queryCache.setQueryData(['user.short-info', response.updated_by_user.id], response.updated_by_user);
      }
      showToastSuccess(
        Object.keys(body).length === 0 ? 'Kickoff notes created successfully' : 'Kickoff notes saved successfully'
      );
      await queryCache.invalidateQueries({ key: ['project.kickoff-notes', projectId], exact: true });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    projectKickoffNotesPatch: mutateAsync,
    isProjectKickoffNotesPatchLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
