import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { isEqual } from 'lodash';
import type { KickoffContact, ProjectKickoffNotes, ProjectKickoffNotesPatchRequest } from '~/client';

const optionalText = z
  .string()
  .trim()
  .optional()
  .transform((s) => (s && s.length > 0 ? s : undefined));

// DatePicker emits a DateValue whose toString() yields 'YYYY-MM-DD'; seeded values arrive as strings.
const optionalDateString = z.preprocess((val) => (val ? String(val) : undefined), z.string().optional());

function optionalNonNegativeNumber(label: string, { integer = false } = {}) {
  // vee-validate's toTypedSchema casts initialValues through this schema, so an untouched field
  // re-validates with the already-transformed number — normalize it back to a string first.
  return z.preprocess(
    (value) => (typeof value === 'number' ? String(value) : value),
    z
      .string()
      .trim()
      .optional()
      .transform((s) => (s && s.length > 0 ? Number(s.replaceAll(',', '')) : undefined))
      .refine((n) => n === undefined || (!Number.isNaN(n) && Number.isFinite(n)), {
        message: `${label} must be a valid number`,
      })
      .refine((n) => n === undefined || n >= 0, { message: `${label} must be zero or greater` })
      .refine((n) => n === undefined || !integer || Number.isInteger(n), {
        message: `${label} must be a whole number`,
      })
  );
}

const yesNoUnset = z.enum(['unset', 'yes', 'no']).optional();

const contactSchema = z.object({
  name: optionalText,
  phone: optionalText,
  email: optionalText,
});

export const schemaObject = {
  // Project summary
  client_name: optionalText,
  primary_contact: contactSchema.optional(),
  supplemental_contacts: z.array(contactSchema).optional(),
  project_description: optionalText,
  locations: optionalText,
  summary_additional_notes: optionalText,
  // Project type
  project_type: optionalText,
  project_type_description: optionalText,
  // Relevant dates
  start_date: optionalDateString,
  end_date: optionalDateString,
  target_completion_date: optionalDateString,
  election_date: optionalDateString,
  possible_disruptions: optionalText,
  other_important_dates: z
    .array(z.object({ label: z.string().trim(), date: optionalDateString }))
    .optional()
    .refine((rows) => rows === undefined || rows.every((row) => row.label.length > 0 && !!row.date), {
      message: 'Each important date needs both a label and a date',
    })
    .refine(
      (rows) => {
        if (rows === undefined) return true;
        const labels = rows.map((row) => row.label).filter((label) => label.length > 0);
        return new Set(labels).size === labels.length;
      },
      { message: 'Each important date needs a unique label' }
    ),
  // Universe description
  total_door_knocks: optionalNonNegativeNumber('Total door knocks', { integer: true }),
  doors_in_universe: optionalNonNegativeNumber('Number of doors in the universe', { integer: true }),
  passes_on_universe: optionalNonNegativeNumber('Number of passes on the universe', { integer: true }),
  door_per_hour_goal: optionalNonNegativeNumber('Door per hour goal'),
  // Reporting & interface
  reporting_contact: contactSchema.optional(),
  meeting_cadence: optionalText,
  report_frequency: optionalText,
  // App, data & literature
  project_app: optionalText,
  app_provided_by: optionalText,
  data_provided_by: optionalText,
  survey_provided_by: optionalText,
  literature_date: optionalDateString,
  app_data_additional_notes: optionalText,
  // Additional notes
  note_taking: yesNoUnset,
  qa_calls: yesNoUnset,
  campaign_apparel_provided: yesNoUnset,
  other_notes: optionalText,
};

const zodObject = z.object(schemaObject);

export type KickoffFormValues = z.infer<typeof zodObject>;
export type KickoffFormInput = z.input<typeof zodObject>;

export const projectKickoffNotesFormSchema = toTypedSchema(zodObject);

/** The API stores free-form notes as either a plain string or a string-to-string map. */
function notesContentToString(value: { [key: string]: string } | string | null | undefined): string {
  if (!value) return '';
  if (typeof value === 'string') return value;
  return Object.entries(value)
    .map(([key, val]) => `${key}: ${val}`)
    .join('\n');
}

function boolToYesNo(value: boolean | null | undefined): 'unset' | 'yes' | 'no' {
  if (value === true) return 'yes';
  if (value === false) return 'no';
  return 'unset';
}

function numberToInput(value: number | null | undefined): string {
  return value === null || value === undefined ? '' : String(value);
}

type ContactFormValue = { name?: string; phone?: string; email?: string };

function contactFromNotes(contact: KickoffContact | null | undefined): { name: string; phone: string; email: string } {
  return { name: contact?.name ?? '', phone: contact?.phone ?? '', email: contact?.email ?? '' };
}

function contactToPayload(contact: ContactFormValue | undefined): KickoffContact | undefined {
  if (!contact) return undefined;
  const result: KickoffContact = { name: contact.name, phone: contact.phone, email: contact.email };
  return result.name || result.phone || result.email ? result : undefined;
}

export function kickoffFormValuesFromNotes(notes: ProjectKickoffNotes | null): KickoffFormInput {
  return {
    client_name: notes?.summary?.client_name ?? '',
    primary_contact: contactFromNotes(notes?.summary?.primary_contact),
    supplemental_contacts: (notes?.summary?.supplemental_contacts ?? []).map(contactFromNotes),
    project_description: notes?.summary?.project_description ?? '',
    locations: notes?.summary?.locations ?? '',
    summary_additional_notes: notesContentToString(notes?.summary?.additional_notes),
    project_type: notes?.project_type?.project_type ?? '',
    project_type_description: notes?.project_type?.description ?? '',
    start_date: notes?.dates?.start_date ?? undefined,
    end_date: notes?.dates?.end_date ?? undefined,
    target_completion_date: notes?.dates?.target_completion_date ?? undefined,
    election_date: notes?.dates?.election_date ?? undefined,
    possible_disruptions: notes?.dates?.possible_disruptions ?? '',
    other_important_dates: Object.entries(notes?.dates?.other_important_dates ?? {}).map(([label, date]) => ({
      label,
      date,
    })),
    total_door_knocks: numberToInput(notes?.universe?.total_door_knocks),
    doors_in_universe: numberToInput(notes?.universe?.doors_in_universe),
    passes_on_universe: numberToInput(notes?.universe?.passes_on_universe),
    door_per_hour_goal: numberToInput(notes?.universe?.door_per_hour_goal),
    reporting_contact: contactFromNotes(notes?.reporting?.reporting_contact),
    meeting_cadence: notes?.reporting?.meeting_cadence ?? '',
    report_frequency: notes?.reporting?.report_frequency ?? '',
    project_app: notes?.app_data_literature?.project_app ?? '',
    app_provided_by: notes?.app_data_literature?.app_provided_by ?? '',
    data_provided_by: notes?.app_data_literature?.data_provided_by ?? '',
    survey_provided_by: notes?.app_data_literature?.survey_provided_by ?? '',
    literature_date: notes?.app_data_literature?.literature_date ?? undefined,
    app_data_additional_notes: notesContentToString(notes?.app_data_literature?.additional_notes),
    qa_calls: boolToYesNo(notes?.additional_notes?.qa_calls),
    campaign_apparel_provided: boolToYesNo(notes?.additional_notes?.campaign_apparel_provided),
    note_taking: boolToYesNo(notes?.additional_notes?.note_taking),
    other_notes: notesContentToString(notes?.additional_notes?.other),
  };
}

function yesNoToBool(value: 'unset' | 'yes' | 'no' | undefined): boolean | undefined {
  if (value === 'yes') return true;
  if (value === 'no') return false;
  return undefined;
}

function kickoffPayloadFromValues(values: KickoffFormValues): ProjectKickoffNotesPatchRequest {
  const contacts = (values.supplemental_contacts ?? [])
    .map(contactToPayload)
    .filter((contact): contact is KickoffContact => contact !== undefined);
  const importantDates = (values.other_important_dates ?? []).filter((row) => row.label.length > 0 && !!row.date);

  return {
    summary: {
      client_name: values.client_name,
      primary_contact: contactToPayload(values.primary_contact),
      supplemental_contacts: contacts.length > 0 ? contacts : undefined,
      project_description: values.project_description,
      locations: values.locations,
      additional_notes: values.summary_additional_notes,
    },
    project_type: {
      project_type: values.project_type,
      description: values.project_type_description,
    },
    dates: {
      start_date: values.start_date,
      end_date: values.end_date,
      target_completion_date: values.target_completion_date,
      election_date: values.election_date,
      possible_disruptions: values.possible_disruptions,
      other_important_dates:
        importantDates.length > 0
          ? Object.fromEntries(importantDates.map((row) => [row.label, row.date as string]))
          : undefined,
    },
    universe: {
      total_door_knocks: values.total_door_knocks,
      doors_in_universe: values.doors_in_universe,
      passes_on_universe: values.passes_on_universe,
      door_per_hour_goal: values.door_per_hour_goal,
    },
    reporting: {
      reporting_contact: contactToPayload(values.reporting_contact),
      meeting_cadence: values.meeting_cadence,
      report_frequency: values.report_frequency,
    },
    app_data_literature: {
      project_app: values.project_app,
      app_provided_by: values.app_provided_by,
      data_provided_by: values.data_provided_by,
      survey_provided_by: values.survey_provided_by,
      literature_date: values.literature_date,
      additional_notes: values.app_data_additional_notes,
    },
    additional_notes: {
      qa_calls: yesNoToBool(values.qa_calls),
      campaign_apparel_provided: yesNoToBool(values.campaign_apparel_provided),
      note_taking: yesNoToBool(values.note_taking),
      other: values.other_notes,
    },
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Build an RFC 7386 merge patch. An omitted key means "unchanged", while null
 * means the user explicitly cleared a value that was present in the snapshot.
 * Arrays are compared and replaced as whole values.
 */
function buildMergePatch(current: unknown, initial: unknown): unknown {
  if (isEqual(current, initial)) return undefined;
  if (current === undefined) return null;
  if (!isRecord(current)) return current;

  const initialRecord = isRecord(initial) ? initial : {};
  const patch: Record<string, unknown> = {};
  const keys = new Set([...Object.keys(initialRecord), ...Object.keys(current)]);

  for (const key of keys) {
    const value = buildMergePatch(current[key], initialRecord[key]);
    if (value !== undefined) patch[key] = value;
  }

  return Object.keys(patch).length > 0 ? patch : undefined;
}

export function buildKickoffPatch(
  values: KickoffFormValues,
  initialValues: KickoffFormInput
): ProjectKickoffNotesPatchRequest {
  const currentPayload = kickoffPayloadFromValues(values);
  const initialPayload = kickoffPayloadFromValues(zodObject.parse(initialValues));
  return (buildMergePatch(currentPayload, initialPayload) ?? {}) as ProjectKickoffNotesPatchRequest;
}
